import 'enums.dart';

/// Immutable record of a single Gatekeeper decision.
///
/// Every inbound agent request produces exactly one entry, regardless
/// of outcome, so the user has a complete tamper-evident trail.
class AuditLogEntry {
  final String logId;

  /// Foreign key into the `Authorized_Agents` table.
  final String agentId;

  /// Natural-language summary of what the agent asked for,
  /// generated by the local SLM before the request is processed.
  final String requestIntent;

  final AuditAction actionTaken;
  final DateTime timestamp;

  const AuditLogEntry({
    required this.logId,
    required this.agentId,
    required this.requestIntent,
    required this.actionTaken,
    required this.timestamp,
  });

  Map<String, dynamic> toMap() => <String, dynamic>{
        'log_id': logId,
        'agent_id': agentId,
        'request_intent': requestIntent,
        'action_taken': actionTaken.value,
        'timestamp': timestamp.toIso8601String(),
      };

  factory AuditLogEntry.fromMap(Map<String, dynamic> map) => AuditLogEntry(
        logId: map['log_id'] as String,
        agentId: map['agent_id'] as String,
        requestIntent: map['request_intent'] as String,
        actionTaken: AuditAction.fromValue(map['action_taken'] as String),
        timestamp: DateTime.parse(map['timestamp'] as String),
      );

  AuditLogEntry copyWith({
    String? logId,
    String? agentId,
    String? requestIntent,
    AuditAction? actionTaken,
    DateTime? timestamp,
  }) =>
      AuditLogEntry(
        logId: logId ?? this.logId,
        agentId: agentId ?? this.agentId,
        requestIntent: requestIntent ?? this.requestIntent,
        actionTaken: actionTaken ?? this.actionTaken,
        timestamp: timestamp ?? this.timestamp,
      );

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is AuditLogEntry &&
          runtimeType == other.runtimeType &&
          logId == other.logId &&
          agentId == other.agentId &&
          requestIntent == other.requestIntent &&
          actionTaken == other.actionTaken &&
          timestamp == other.timestamp;

  @override
  int get hashCode => Object.hash(
        logId,
        agentId,
        requestIntent,
        actionTaken,
        timestamp,
      );

  @override
  String toString() => 'AuditLogEntry(logId: $logId)';
}
